// The images and graphics objects here are disposed explicitly, the analyzer can't follow all of it.
#pragma warning disable CA2000

using System;
using System.Diagnostics;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.IO;
using System.Threading;
using System.Windows.Forms;

namespace bnetlauncher.Utils
{
    /// <summary>
    /// Large "Preparing Your Adventure!" window shown while bnetlauncher gets the game started.
    /// It runs on it's own thread so it keeps painting even when the rest of the program is busy,
    /// it never takes the focus and mouse clicks go right through it, so it doesn't get in the
    /// way of the clicks bnetlauncher sends to the battle.net client underneath.
    /// Each game has it's own picture, games without one don't show the window.
    /// </summary>
    internal static class Splash
    {
        private const string Caption = "Preparing Your Adventure!";

        // The window never stays open longer than this, even if something goes wrong.
        private const int MaxShowSeconds = 150;

        private static readonly object sync = new object();
        private static SplashForm form;
        private static Thread thread;

        /// <summary>
        /// Shows the window for the game with the given product code (if it has a picture and
        /// the window isn't already showing).
        /// </summary>
        public static void Show(string product_code)
        {
            var image_data = SplashImageData.ForProduct(product_code);
            if (image_data == null)
            {
                Logger.Information($"No splash picture for '{product_code}', not showing the splash window.");
                return;
            }

            lock (sync)
            {
                if (thread != null)
                {
                    return;
                }

                using (var ready = new ManualResetEvent(false))
                {
                    thread = new Thread(() =>
                    {
                        try
                        {
                            var splash = new SplashForm(image_data);
                            splash.Shown += (sender, e) => ready.Set();
                            form = splash;
                            Application.Run(splash);
                        }
                        catch (Exception ex)
                        {
                            Logger.Error("Splash window failed.", ex);
                        }
                        finally
                        {
                            try { ready.Set(); } catch (ObjectDisposedException) { }
                        }
                    });
                    thread.SetApartmentState(ApartmentState.STA);
                    thread.IsBackground = true;
                    thread.Start();

                    // Gives it a moment to appear so it's there before the rest of the work starts.
                    ready.WaitOne(3000);
                }
            }
        }

        /// <summary>
        /// Hides the window without closing it, used when another window needs the attention.
        /// </summary>
        public static void Hide()
        {
            SetVisible(false);
        }

        /// <summary>
        /// Shows the window again after Hide.
        /// </summary>
        public static void Unhide()
        {
            SetVisible(true);
        }

        /// <summary>
        /// Closes the window.
        /// </summary>
        public static void Close()
        {
            SplashForm closing;
            lock (sync)
            {
                closing = form;
                form = null;
                thread = null;
            }

            RunOnWindowThread(closing, () => closing.Close());
        }

        /// <summary>
        /// Keeps the window up until the process shows it's own window (or the timeout is reached) and closes it.
        /// </summary>
        public static void CloseWhenWindowAppears(Process process, int timeout_seconds)
        {
            try
            {
                if (process != null)
                {
                    var start = DateTime.Now;
                    while (DateTime.Now.Subtract(start).TotalSeconds < timeout_seconds)
                    {
                        process.Refresh();
                        if (process.HasExited || process.MainWindowHandle != IntPtr.Zero)
                        {
                            break;
                        }
                        Thread.Sleep(250);
                    }
                }
            }
            catch (Exception ex)
            {
                Logger.Warning($"Couldn't wait for the game window: {ex.Message}");
            }

            Close();
        }

        private static void SetVisible(bool visible)
        {
            SplashForm current;
            lock (sync)
            {
                current = form;
            }

            RunOnWindowThread(current, () => current.Visible = visible);
        }

        private static void RunOnWindowThread(SplashForm target, Action action)
        {
            if (target == null)
            {
                return;
            }

            try
            {
                if (target.IsHandleCreated && !target.IsDisposed)
                {
                    target.BeginInvoke(action);
                }
            }
            catch (Exception ex)
            {
                Logger.Warning($"Splash window update failed: {ex.Message}");
            }
        }

        /// <summary>
        /// Loads the picture and writes the caption right on top of it.
        /// </summary>
        private static Bitmap LoadImage(string base64)
        {
            try
            {
                var bytes = Convert.FromBase64String(base64);

                Bitmap bitmap;
                using (var stream = new MemoryStream(bytes))
                using (var source = Image.FromStream(stream))
                {
                    // The image is copied into a bitmap so the stream can be closed right away.
                    bitmap = new Bitmap(source);
                }

                DrawCaption(bitmap);
                return bitmap;
            }
            catch (Exception ex)
            {
                Logger.Warning($"Couldn't load splash image: {ex.Message}");
                return null;
            }
        }

        /// <summary>
        /// Writes the caption near the bottom of the picture, white with a dark outline so it can be
        /// read on top of any picture without needing a background bar.
        /// </summary>
        private static void DrawCaption(Bitmap bitmap)
        {
            float size = bitmap.Height * 0.075f;
            var area = new RectangleF(0, bitmap.Height * 0.83f, bitmap.Width, bitmap.Height * 0.15f);

            FontFamily family;
            try
            {
                family = new FontFamily("Segoe UI");
            }
            catch (ArgumentException)
            {
                family = FontFamily.GenericSansSerif;
            }

            try
            {
                using (var graphics = Graphics.FromImage(bitmap))
                using (var path = new GraphicsPath())
                using (var format = new StringFormat())
                using (var fill = new SolidBrush(Color.White))
                using (var outline = new Pen(Color.Black, size * 0.18f))
                {
                    format.Alignment = StringAlignment.Center;
                    format.LineAlignment = StringAlignment.Center;
                    outline.LineJoin = LineJoin.Round;

                    graphics.SmoothingMode = SmoothingMode.AntiAlias;
                    path.AddString(Caption, family, (int)FontStyle.Bold, size, area, format);

                    // Outline first, then the white fill on top so the letters stay clean.
                    graphics.DrawPath(outline, path);
                    graphics.FillPath(fill, path);
                }
            }
            finally
            {
                if (family != FontFamily.GenericSansSerif)
                {
                    family.Dispose();
                }
            }
        }

        private sealed class SplashForm : Form
        {
            public SplashForm(string image_data)
            {
                var area = Screen.PrimaryScreen.WorkingArea;
                int width = Math.Max(800, Math.Min(1280, area.Width / 2));
                int height = width * 9 / 16;

                FormBorderStyle = FormBorderStyle.None;
                StartPosition = FormStartPosition.Manual;
                ShowInTaskbar = false;
                TopMost = true;
                BackColor = Color.Black;
                ClientSize = new Size(width, height);
                Location = new Point(area.Left + (area.Width - Width) / 2, area.Top + (area.Height - Height) / 2);

                // Anything below 1 makes the window "layered" which is needed for clicks to go through it.
                Opacity = 0.99;

                Controls.Add(new PictureBox
                {
                    Dock = DockStyle.Fill,
                    SizeMode = PictureBoxSizeMode.StretchImage,
                    Image = LoadImage(image_data)
                });

                // Safety net: the window closes itself if nothing else closed it, so it can never stay on screen.
                var timer = new System.Windows.Forms.Timer { Interval = MaxShowSeconds * 1000 };
                timer.Tick += (sender, e) =>
                {
                    Logger.Warning("Splash window was open for too long, closing it.");
                    Close();
                };
                FormClosed += (sender, e) => timer.Dispose();
                timer.Start();
            }

            // Don't take the focus when shown.
            protected override bool ShowWithoutActivation
            {
                get { return true; }
            }

            protected override CreateParams CreateParams
            {
                get
                {
                    var cp = base.CreateParams;

                    // WS_EX_LAYERED | WS_EX_TRANSPARENT (clicks go through) | WS_EX_TOOLWINDOW | WS_EX_NOACTIVATE
                    cp.ExStyle |= 0x00080000 | 0x00000020 | 0x00000080 | 0x08000000;
                    return cp;
                }
            }
        }
    }

    /// <summary>
    /// The pictures shown in the splash window, JPEGs stored as base64 text.
    /// </summary>
    internal static class SplashImageData
    {
        /// <summary>
        /// Gets the picture for a game by it's battle.net product code, or null if it doesn't have one.
        /// </summary>
        public static string ForProduct(string product_code)
        {
            if (String.Equals(product_code, "wowf", StringComparison.OrdinalIgnoreCase))
            {
                return Forever;
            }

            if (String.Equals(product_code, "wow_anniversary", StringComparison.OrdinalIgnoreCase) ||
                String.Equals(product_code, "wow_classic_anniversary", StringComparison.OrdinalIgnoreCase))
            {
                return Anniversary;
            }

            return null;
        }

